import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(1, in, out);
        out.close();
    }

    static class Solver {
        Arithmetic arith = new Arithmetic();
        int n;
        int m;

        void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            arith.prepare(n + m);

            long phaseSize = 1;
            long p = 1;
            for (int i = 0; p != 0; i++) {
                p = arith.mul(arith.mul(p, n - i), arith.smallInv(n + m - i));
                phaseSize = arith.add(phaseSize, p);
            }

            long answer = 0;
            for (int k = 1; k <= n; k++) {
                long numPhases = arith.mul(m + k, arith.smallInv(k));
                long term = arith.mul(arith.ncr(n, k), arith.mul(numPhases, phaseSize));
                if ((k & 1) == 1) answer = arith.add(answer, term);
                else answer = arith.sub(answer, term);
            }

            out.println(answer);
        }
    }

    static class Arithmetic {
        static final long MOD = 998244353L;
        ArrayList<Integer> fact = new ArrayList<>();
        ArrayList<Integer> invFact = new ArrayList<>();

        Arithmetic() {
            fact.add(1);
            invFact.add(1);
        }

        void prepare(int n) {
            while (fact.size() <= n) {
                int len = fact.size();
                fact.add((int) mul(fact.get(len - 1), len));
            }
            if (invFact.size() <= n) {
                int last = invFact.size() - 1;
                long fInv = inv(fact.get(n));
                int[] temp = new int[n - last];
                temp[0] = (int) fInv;
                for (int i = 1; i < temp.length; i++) {
                    temp[i] = (int) mul(temp[i - 1], n - i + 1);
                }
                for (int i = temp.length - 1; i >= 0; i--) {
                    invFact.add((int) temp[i]);
                }
            }
        }

        long fact(int n) {
            prepare(n);
            return fact.get(n);
        }

        long fInv(int n) {
            prepare(n);
            return invFact.get(n);
        }

        long ncr(int n, int r) {
            if (r < 0 || r > n) return 0;
            return mul(fact(n), mul(fInv(r), fInv(n - r)));
        }

        long smallInv(int n) {
            return mul(fInv(n), fact(n - 1));
        }

        long add(long a, long b) {
            long v = a + b;
            return v >= MOD ? v - MOD : v;
        }

        long sub(long a, long b) {
            long v = a - b;
            return v < 0 ? v + MOD : v;
        }

        long mul(long a, long b) {
            return a * b % MOD;
        }

        long inv(long value) {
            long g = MOD, x = 0, y = 1;
            for (long r = value; r != 0; ) {
                long q = g / r;
                g %= r;

                long tmp = g;
                g = r;
                r = tmp;

                x -= q * y;

                tmp = x;
                x = y;
                y = tmp;
            }
            if (g != 1) throw new AssertionError();
            x %= MOD;
            if (x < 0) x += MOD;
            return x;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
